+  static func parseJJRemoteList(_ stdout: String) -> [String] {
+    var remotes: [String] = []
+    for line in stdout.split(whereSeparator: \.isNewline) {
+      let row = String(line)
+      guard let lastSpace = row.lastIndex(of: " ") else { continue }
+      let name = String(row[row.startIndex..<lastSpace])
